// Desktop 2.0 snapshot: src/shared/loudness.ts. Generated by scripts/import-pc-2.mjs; platform adaptations are explicit in that script.
// Громкость по EBU R128 / ITU-R BS.1770 (версия 1.7): K-взвешивание (полка +4 дБ на высоких и срез ниже 38 Гц),
// блоки 400 мс с перекрытием 75%, абсолютный порог -70 LUFS и относительный -10 LU.
// Счётчик получает звук кусками любого размера: целиком раскодированный файл или куски из живого звука.
// Тут же правило усиления: сколько дБ добавить песне, чтобы она звучала на целевом уровне.

/** Целевые уровни «Тихо / Нормально / Громко» (крупные сервисы держат около -14 LUFS). */
export const LOUDNESS_TARGETS = { quiet: -18, normal: -14, loud: -11 } as const;
export type LoudnessLevel = keyof typeof LOUDNESS_TARGETS;
/** Тише цели песню поднимаем не больше чем на столько (дальше перегруз ловит ограничитель, но и он не всесилен). */
export const MAX_BOOST_DB = 6;
/** Пока громкость песни неизвестна: средняя громкость современных записей (песня чуть тише, чем могла бы, но не громче). */
export const UNKNOWN_LUFS = -10;

/** Сколько дБ добавить (минус: убавить). */
export function normalizationGainDb(lufs: number | null, target: number): number {
  const l = lufs ?? UNKNOWN_LUFS;
  return Math.min(MAX_BOOST_DB, Math.max(-24, target - l));
}

export const dbToGain = (db: number) => Math.pow(10, db / 20);

interface Biquad {
  b0: number;
  b1: number;
  b2: number;
  a1: number;
  a2: number;
}

/** Коэффициенты K-фильтра для частоты дискретизации (формулы RBJ, как в pyloudnorm). */
export function kWeighting(fs: number): [Biquad, Biquad] {
  // Ступень 1: полка +4 дБ выше ~1,5 кГц (так ухо слышит голову и уши)
  const A = Math.pow(10, 4.0 / 40);
  let w0 = (2 * Math.PI * 1500.0) / fs;
  let cos = Math.cos(w0);
  let alpha = Math.sin(w0) / (2 * (1 / Math.SQRT2));
  const sA = 2 * Math.sqrt(A) * alpha;
  let a0 = A + 1 - (A - 1) * cos + sA;
  const shelf: Biquad = {
    b0: (A * (A + 1 + (A - 1) * cos + sA)) / a0,
    b1: (-2 * A * (A - 1 + (A + 1) * cos)) / a0,
    b2: (A * (A + 1 + (A - 1) * cos - sA)) / a0,
    a1: (2 * (A - 1 - (A + 1) * cos)) / a0,
    a2: (A + 1 - (A - 1) * cos - sA) / a0,
  };
  // Ступень 2: срез ниже 38 Гц
  w0 = (2 * Math.PI * 38.0) / fs;
  cos = Math.cos(w0);
  alpha = Math.sin(w0) / (2 * 0.5);
  a0 = 1 + alpha;
  const hp: Biquad = {
    b0: (1 + cos) / 2 / a0,
    b1: -(1 + cos) / a0,
    b2: (1 + cos) / 2 / a0,
    a1: (-2 * cos) / a0,
    a2: (1 - alpha) / a0,
  };
  return [shelf, hp];
}

/** Состояние одного фильтра одного канала. */
class Filter {
  private x1 = 0;
  private x2 = 0;
  private y1 = 0;
  private y2 = 0;
  constructor(private c: Biquad) {}
  run(x: number): number {
    const { b0, b1, b2, a1, a2 } = this.c;
    const y = b0 * x + b1 * this.x1 + b2 * this.x2 - a1 * this.y1 - a2 * this.y2;
    this.x2 = this.x1;
    this.x1 = x;
    this.y2 = this.y1;
    this.y1 = y;
    return y;
  }
}

/** Интегральная громкость по накопленным блокам 400 мс (средние квадраты, уже сложенные по каналам). */
export function gatedLoudness(blocks: number[]): number | null {
  const lk = (z: number) => -0.691 + 10 * Math.log10(z);
  const abs = blocks.filter((z) => z > 0 && lk(z) > -70);
  if (!abs.length) return null;
  const mean = (a: number[]) => a.reduce((s, z) => s + z, 0) / a.length;
  const rel = lk(mean(abs)) - 10;
  const gated = abs.filter((z) => lk(z) > rel);
  return gated.length ? lk(mean(gated)) : null;
}

/**
 * Счётчик громкости. Куски по 100 мс (четверть блока): каждые 4 подряд дают блок 400 мс, шаг 100 мс (перекрытие 75%).
 * push можно вызывать с кусками любой длины; разрывы между кусками (живой звук) допустимы, это даёт оценку.
 */
export class LoudnessMeter {
  private filters: [Filter, Filter][] = [];
  private step: number;
  private acc = 0;
  private n = 0;
  private quarters: number[] = [];
  readonly blocks: number[] = [];

  constructor(
    private fs: number,
    channels: number,
  ) {
    const [a, b] = kWeighting(fs);
    for (let c = 0; c < channels; c++) this.filters.push([new Filter(a), new Filter(b)]);
    this.step = Math.round(fs * 0.1);
  }

  /** Сколько секунд звука учтено. */
  get seconds(): number {
    return (this.quarters.length * this.step + this.n) / this.fs;
  }

  push(channels: Float32Array[], length = channels[0]?.length ?? 0): void {
    const ch = Math.min(channels.length, this.filters.length);
    for (let i = 0; i < length; i++) {
      let s = 0;
      for (let c = 0; c < ch; c++) {
        const [f1, f2] = this.filters[c];
        const y = f2.run(f1.run(channels[c][i]));
        s += y * y;
      }
      this.acc += s;
      if (++this.n === this.step) {
        this.quarters.push(this.acc / this.step);
        this.acc = 0;
        this.n = 0;
        const q = this.quarters.length;
        if (q >= 4) this.blocks.push((this.quarters[q - 1] + this.quarters[q - 2] + this.quarters[q - 3] + this.quarters[q - 4]) / 4);
      }
    }
  }

  /** Интегральная громкость, LUFS (null: слишком тихо или мало звука). */
  integrated(): number | null {
    return gatedLoudness(this.blocks);
  }
}
